import pandas as pd
df = pd.read_csv('data/restaurants/clean_restaurant_2022.csv')
ohio_cities = ['Cleveland', 'Columbus', 'Cincinnati']
df = df[df['City'].isin(ohio_cities)].copy()

def has_cuisine(cuisines, target):
    if pd.isna(cuisines):
        return False
    for c in cuisines.split(','):
        if target.lower() in c.strip().lower():
            return True
    return False

for cuisine in ['American', 'Mediterranean', 'Chinese', 'Italian']:
    df[f'has_{cuisine}'] = df['Cuisines'].apply(lambda x: has_cuisine(x, cuisine))

# Print restaurants in each city that have any of these cuisines
for city in ohio_cities:
    print(f'=== {city} ===')
    sub = df[df['City'] == city]
    for cuisine in ['American', 'Mediterranean', 'Chinese', 'Italian']:
        csub = sub[sub[f'has_{cuisine}']].sort_values('Average Cost')
        print(f'  {cuisine}:')
        for _, r in csub.iterrows():
            print(f'    {r[\"Name\"]} | cost: {r[\"Average Cost\"]} | cuisines: {r[\"Cuisines\"]} | rating: {r[\"Aggregate Rating\"]}')
    print()
"

