import json
with open('output/itinerary.json') as f:
    data = json.load(f)

# Check cuisine types
cuisines = ['American', 'Mediterranean', 'Chinese', 'Italian']
for c in cuisines:
    count = 0
    for day in data['plan']:
        for meal in ['breakfast', 'lunch', 'dinner']:
            if c in day[meal]:
                count += 1
    print(f'{c}: {count} mentions')

# Check no flights
for day in data['plan']:
    if 'flight' in str(day['transportation']).lower():
        print(f'ERROR: Flight detected on day {day[\"day\"]}')
    else:
        print(f'Day {day[\"day\"]}: no flights, transport={day[\"transportation\"]}')

# Check 3 Ohio cities covered
ohio_cities = ['Cleveland', 'Columbus', 'Cincinnati']
mentioned = set()
for day in data['plan']:
    s = str(day)
    for city in ohio_cities:
        if city in s:
            mentioned.add(city)
print(f'Ohio cities mentioned: {mentioned}')
"

