python3 << 'EOF'
import json
import pandas as pd

with open('output/itinerary.json') as f:
    data = json.load(f)

# Load data
df_acc = pd.read_csv('data/accommodations/clean_accommodations_2022.csv')
df_rest = pd.read_csv('data/restaurants/clean_restaurant_2022.csv')
df_attr = pd.read_csv('data/attractions/attractions.csv')

# Get all valid names
valid_acc_names = set(df_acc['NAME'].tolist())
valid_rest_names = set(df_rest['Name'].tolist())
valid_attr_names = set(df_attr['Name'].tolist())

# Check each day
for day in data['plan']:
    acc = day['accommodation']
    # Extract accommodation name (after "Pet-friendly ")
    if 'Pet-friendly ' in acc:
        acc_name = acc.replace('Pet-friendly ', '').split(', ')[0]
        # Strip possible trailing city name
        if acc_name not in valid_acc_names:
            # Try removing ", CITY"
            for city in ['Cleveland', 'Columbus', 'Cincinnati', 'Minneapolis']:
                test_name = acc_name.replace(f', {city}', '')
                if test_name in valid_acc_names:
                    acc_name = test_name
                    break
            else:
                if acc_name not in valid_acc_names:
                    print(f"Day {day['day']}: ACCOMMODATION NOT FOUND: {acc_name}")
                else:
                    print(f"Day {day['day']}: ACCOMMODATION OK: {acc_name}")
        else:
            print(f"Day {day['day']}: ACCOMMODATION OK: {acc_name}")

    # Check restaurants in meals
    for meal in ['breakfast', 'lunch', 'dinner']:
        m = day[meal]
        if m == '-':
            continue
        # Try to find restaurant name
        # Pattern: "[Cuisine] at [Name], [City]" or "[Name], [City]"
        import re
        # Look for "at NAME" or "cuisine at NAME"
        m_match = re.search(r'at (.+?),', m)
        if m_match:
            rname = m_match.group(1)
            if rname not in valid_rest_names:
                print(f"Day {day['day']} {meal}: RESTAURANT NOT FOUND: {rname}")
            else:
                pass
        else:
            # Pattern: "NAME, City"
            m_match = re.match(r'(.+?),', m)
            if m_match:
                rname = m_match.group(1)
                # Strip leading cuisine
                rname = re.sub(r'^(American cuisine|Mediterranean cuisine|Italian cuisine|Chinese cuisine)\s*', '', rname)
                if rname not in valid_rest_names:
                    print(f"Day {day['day']} {meal}: RESTAURANT NOT FOUND: {rname}")

    # Check attractions
    attr = day['attraction']
    if attr == '-':
        continue
    for a in attr.split(';'):
        if not a:
            continue
        if a not in valid_attr_names:
            print(f"Day {day['day']}: ATTRACTION NOT FOUND: {a}")
EOF

